import limited_client as robot,numpy as np
x=robot.observe('corner4');im=x['rgb'];d=x['depth_m'];K=x['intrinsic'];T=x['camera_to_world'];
for box in [(165,215,225,260),(175,220,230,255)]:
 u0,v0,u1,v1=box; yy,xx=np.mgrid[v0:v1,u0:u1];q=im[v0:v1,u0:u1];z=d[v0:v1,u0:u1];m=(q[:,:,0]>70)&(q[:,:,0]>q[:,:,1]*1.4)&(q[:,:,0]>q[:,:,2]*1.2)&(z>1)&(z<1.3)
 coords=[]
 for a,b,c in zip(xx[m],yy[m],z[m]): coords.append((T@np.array([(a-240)*c/K[0,0],(b-240)*c/K[1,1],c,1]))[:3])
 coords=np.array(coords);print(box,'n',len(coords))
 if len(coords):print('ranges',coords.min(0),coords.max(0),'median',np.median(coords,0))
 for p in [(172,255),(180,248),(190,243),(200,240),(210,237),(220,235)]:
  a,b=p;c=d[b,a];pix=im[b,a];w=(T@np.array([(a-240)*c/K[0,0],(b-240)*c/K[1,1],c,1]))[:3];print(p,pix.tolist(),round(c,3),np.round(w,3))
 break
